function sumScores(s) {
  const n = s.length;
  const z = new Array(n).fill(0);
  z[0] = n;
  let left = 0;
  let right = 0;
  let total = n;

  for (let i = 1; i < n; i++) {
    if (i < right) {
      z[i] = Math.min(right - i, z[i - left]);
    }
    while (i + z[i] < n && s[z[i]] === s[i + z[i]]) {
      z[i]++;
    }
    if (i + z[i] > right) {
      left = i;
      right = i + z[i];
    }
    total += z[i];
  }
  return total;
}

