function sumScores(s) {
  let sum = 0;
  for (let start = 0; start < s.length; start++) {
    let k = 0;
    while (start + k < s.length && s.charAt(k) === s.charAt(start + k)) k++;
    sum += k;
  }
  return sum;
}

