function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const n = size === 'large' ? 6000 + Math.floor(rand() * 4001) : 1 + Math.floor(rand() * 12);
  const kinds = Math.floor(rand() * 4);
  if (kinds === 0) {
    // Repeat a short random block, which creates long shared prefixes.
    const blockLength = 1 + Math.floor(rand() * (size === 'large' ? 6 : 3));
    let block = '';
    for (let i = 0; i < blockLength; i++) block += letters[Math.floor(rand() * 3)];
    let s = '';
    while (s.length < n) s += block;
    return [s.slice(0, n)];
  }
  if (kinds === 1) {
    // Mostly one letter with a few others sprinkled in.
    let s = '';
    for (let i = 0; i < n; i++) s += rand() < 0.05 ? letters[1 + Math.floor(rand() * 2)] : 'a';
    return [s];
  }
  const alphabet = kinds === 2 ? 2 : 1 + Math.floor(rand() * 26);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * alphabet)];
  return [s];
}
